/**
 * A glyph from Material Symbols Rounded: SVG path data, the viewport it is drawn in (24 for the classic set, 960 for
 * [Symbols]) and the viewport's top edge (-960 for [Symbols], whose SVGs put the origin at the bottom left).
 */
data class Icon(val path: String, val viewport: Float = 24f, val top: Float = 0f)

/** A glyph drawn as a vector, [size] square, in [color]. */
@Composable
fun Glyph(icon: Icon, color: Color, size: Dp, modifier: Modifier = Modifier) {
    val path = remember(icon) { PathParser().parsePathString(icon.path).toPath() }
    Canvas(modifier.size(size)) {
        val s = this.size.width / icon.viewport
        scale(s, s, pivot = Offset.Zero) { translate(0f, -icon.top) { drawPath(path, color) } }
    }
}

